void fn_800C849C(void *object, Vec3 *position, float step)
{
    Vec3 copy = *position;
    float target = fn_8012B7D0(object, &copy);
    double raw_current = fn_8012B750(object);
    float current = raw_current;
    float difference;
    fn_8017A12C(&difference, (float)raw_current, target);
    if ((difference < lbl_8064F21C ? -difference : difference) > lbl_8064F24C) {
        fn_8017A010((float *)&current, 0, target, step, lbl_8064F24C);
        fn_8012B7A0(object, current);
    }
}

