import json,re
from pathlib import Path
d=json.loads(Path("reports/GEDE01/objdiff-f81b110e-2fec-47b3-9bdf-1ae8c4303139.json").read_text())
v=next(x for x in d["verification"] if "functionRelocDiffs=all" in x["argv"])
assert v["exit_code"] == 0
raw=json.loads(v["stdout"])
elfrows=[]
for v in d["verification"]:
 if v["argv"][0].endswith("readelf"):
  assert v["exit_code"] == 0
  parsed={}
  for line in v["stdout"].splitlines():
   m=re.match(r"([0-9a-f]+)\s+([0-9a-f]+)\s+(R_PPC_\w+)\s+[0-9a-f]+\s+(\S+)\s+([+-])\s+([0-9a-f]+)$",line.strip())
   if m:
    offset,info,typ,target,sign,addend=m.groups()
    parsed[int(offset,16)]={"offset":int(offset,16),"type":typ,"target":target,"addend":int(addend,16)*(-1 if sign=="-" else 1)}
  elfrows.append(parsed)
assert len(elfrows)==2
rows={}
for side,elf in zip(("left","right"),elfrows):
 fn=next(s for s in raw[side]["symbols"] if s["name"]=="fn_800C849C")
 rows[side]=[]
 print(side,"size",fn["size"],"match_percent",fn["match_percent"])
 for row in fn["instructions"]:
  ins=row.get("instruction",{});rel=ins.get("relocation")
  if rel:
   resolved=elf[int(ins["address"])]
   assert resolved["type"]==rel["type_name"]
   assert resolved["addend"]==int(rel.get("addend",0))
   assert resolved["target"] in ins["formatted"]
   print("objdiff target_symbol",rel["target_symbol"],"resolved via ELF relocation:",json.dumps(resolved))
   rows[side].append(resolved)
 assert len(rows[side])==len(elf)==7
assert rows["left"]==rows["right"]
print("PASS: all seven relocations agree in instruction offset, type, ELF-resolved target name, and explicit ELF addend.")

